3	import (
4		"errors"
5		"path/filepath"
6		"testing"
7	)
8	
9	// 本文件为“器具登记信息返回结果”的既有行为提供自动化回归保障：
10	// 登记成功、按编号查询、列出器具与按器具核对返回的器具信息都是独立展示副本，
11	// 调用方对副本（编号、名称、允许误差、状态、登记时间）的整理不回写台账，
12	// 不释放或占用编号、不改变器具数量，也不影响使用资格判断与证书归属。
13	// 范围只涉及器具信息，不扩展到证书、使用原因或计划结果的副本测试。
14	
15	// 先按正式登记信息断言一件器具，测试辅助。
16	func assertOfficialInstrument(t *testing.T, l *Ledger, id, name string, allowed float64, status Status, registeredAt string) {
17		t.Helper()
18		got, err := l.Instrument(id)
19		if err != nil {
20			t.Fatalf("按原编号 %s 查询应仍存在：%v", id, err)
21		}
22		if got.ID != id || got.Name != name || got.AllowedError != allowed ||
23			got.Status != status || got.RegisteredAt != registeredAt {
24			t.Fatalf("正式登记信息与保存内容不符：%+v", got)
25		}
26	}
27	
28	// TestReturnedRegisterResultCannotRewriteLedger 对应核心场景：登记成功返回的
29	// 器具副本被全面整理（改编号、名称、允许误差、状态、登记时间）后，按原编号
30	// 查询、列出器具与核对仍得到实际保存的登记信息；原编号不释放、新编号不占用、
31	// 器具数量不增加；随后一次正常写盘也不把展示内容带入台账文件。
32	func TestReturnedRegisterResultCannotRewriteLedger(t *testing.T) {
33		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
34		path := filepath.Join(t.TempDir(), "ledger.json")
35		l, err := openAt(path, clock.now)
36		if err != nil {
37			t.Fatalf("open: %v", err)
38		}
39		mustRegister(t, l, "M-2", "示波器", 1.0)
40	
41		registered, err := l.Register(RegisterInput{ID: "M-1", Name: " 万用表 ", AllowedError: 0.5})
42		if err != nil {
43			t.Fatalf("register: %v", err)
44		}
45		if registered.ID != "M-1" || registered.Name != "万用表" ||
46			registered.AllowedError != 0.5 || registered.Status != StatusPending {
47			t.Fatalf("登记返回结果内容异常：%+v", registered)
48		}
49		savedAt := registered.RegisteredAt
50		if savedAt == "" {
51			t.Fatal("登记时间不应为空")
52		}
53	
54		// 调用方整理返回结果：编号改成尚不存在的编号，并改动全部其他字段。
55		registered.ID = "M-NEW"
56		registered.Name = "展示用名称"
57		registered.AllowedError = 9.9
58		registered.Status = StatusInUse
59		registered.RegisteredAt = "2099-01-01T00:00:00Z"
60	
61		// 原器具没有消失，查询、列出、核对都仍是实际保存的登记信息。
62		assertOfficialInstrument(t, l, "M-1", "万用表", 0.5, StatusPending, savedAt)
63		list := l.Instruments()
64		if len(list) != 2 {
65			t.Fatalf("正式器具数量应保持 2 件，得到 %d 件：%+v", len(list), list)
66		}
67		var listed *Instrument
68		for i := range list {
69			if list[i].ID == "M-1" {
70				listed = &list[i]
71			}
72		}
73		if listed == nil || listed.Name != "万用表" || listed.AllowedError != 0.5 ||
74			listed.Status != StatusPending || listed.RegisteredAt != savedAt {
75			t.Fatalf("列出器具被返回结果改写：%+v", list)
76		}
77		r, err := l.Review("M-1")
78		if err != nil {
79			t.Fatalf("review: %v", err)
80		}
81		if r.Instrument.ID != "M-1" || r.Instrument.Name != "万用表" ||
82			r.Instrument.AllowedError != 0.5 || r.Instrument.Status != StatusPending ||
83			r.Instrument.RegisteredAt != savedAt {
84			t.Fatalf("核对中的登记信息被返回结果改写：%+v", r.Instrument)
85		}
86	
87		// 原编号未释放：再登记原编号仍被拒绝；副本中的新编号不存在、未占用。
88		if _, err := l.Register(RegisterInput{ID: "M-1", Name: "另一件", AllowedError: 0.1}); !IsValidation(err) {
89			t.Fatalf("原编号仍应占用、重复登记被拒绝，得到 %v", err)
90		}
91		if _, err := l.Instrument("M-NEW"); err == nil {
92			t.Fatal("只在副本中出现的新编号不应能查到")
93		} else if !errors.Is(err, ErrNotFound) {
94			t.Fatalf("新编号查询应报告不存在，得到 %v", err)
95		}
96		// 新编号未被占用：用它登记应成功，台账变为 3 件，原器具仍在。
97		mustRegister(t, l, "M-NEW", "真新器具", 0.2)
98		if len(l.Instruments()) != 3 {
99			t.Fatalf("副本改写未新增器具，正式登记 M-NEW 后应为 3 件，得到 %d 件", len(l.Instruments()))
100		}
101		assertOfficialInstrument(t, l, "M-1", "万用表", 0.5, StatusPending, savedAt)
102	
103		// 正常状态切换保存后重开同一台账，读到的仍是正式登记信息与真实状态。
104		if err := l.SetStatus("M-1", StatusRetired); err != nil {
105			t.Fatalf("set status: %v", err)
106		}
107		reopened, err := openAt(path, clock.now)
108		if err != nil {
109			t.Fatalf("reopen: %v", err)
110		}
111		if len(reopened.Instruments()) != 3 {
112			t.Fatalf("重开后器具数量应为 3，得到 %d", len(reopened.Instruments()))
113		}
114		got, err := reopened.Instrument("M-1")
115		if err != nil {
116			t.Fatalf("reopen instrument: %v", err)
117		}
118		if got.Name != "万用表" || got.AllowedError != 0.5 || got.Status != StatusRetired ||
119			got.RegisteredAt != savedAt {
120			t.Fatalf("展示内容被写盘带入台账：%+v", got)
121		}
122	}
123	
124	// TestReturnedInstrumentMutationCannotRaiseLimitOrLiftRetirement 验证器具信息
125	// 副本对使用资格判断没有影响：
126	//   - 在用器具证书未到期但测得误差超过登记限值时，把副本允许误差调大，
127	//     核对仍显示超差、申请使用仍被拒绝，原因仍按正式限值说明；
128	//   - 停用器具即使有合格且未到期的证书，把副本状态改成在用也不能解除停用；
129	//   - 原本允许使用的器具，不会因为副本被调低限值或改成停用而失去资格。
130	func TestReturnedInstrumentMutationCannotRaiseLimitOrLiftRetirement(t *testing.T) {
131		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
132		l := newTestLedger(t, clock)
133	
134		// M-1：在用，登记限值 0.5；证书测得 0.8，未到期——正式数据为超差。
135		mustRegister(t, l, "M-1", "万用表", 0.5)
136		_ = l.SetStatus("M-1", StatusInUse)
137		mustAddCert(t, l, CertificateInput{
138			InstrumentID: "M-1", Number: "C-1", CalDate: "2026-09-01",
139			Expiry: "2027-09-01", Method: "m", Error: 0.8, Summary: "超差批次",
140		})
141		over, err := l.Instrument("M-1")
142		if err != nil {
143			t.Fatalf("instrument: %v", err)
144		}
145		over.AllowedError = 100
146	
147		// 分别从按编号查询、列出与核对三个入口取得副本并调大限值。
148		if list := l.Instruments(); len(list) != 1 {
149			t.Fatalf("应只有一件器具，得到 %d", len(list))
150		} else {
151			list[0].AllowedError = 100
152		}
153		rv, err := l.Review("M-1")
154		if err != nil {
155			t.Fatalf("review: %v", err)
156		}
157		rv.Instrument.AllowedError = 100
158		if rv.Latest == nil || rv.Latest.Pass {
159			t.Fatalf("核对仍应按正式限值判定超差，得到 %+v", rv.Latest)
160		}
161		if rv.CanUse || !containsReason(rv.Reasons, "超差") ||
162			!containsReason(rv.Reasons, "0.5") {
163			t.Fatalf("调大副本限值不应解除超差限制，原因应按正式限值 0.5 说明，得到 %v", rv.Reasons)
164		}
165		d, err := l.CanUse("M-1")
166		if err != nil || d.Allowed {
167			t.Fatalf("调大副本限值后申请使用仍应被拒绝，err=%v allowed=%v", err, d.Allowed)
168		}
169		if !containsReason(d.Reasons, "超差") || !containsReason(d.Reasons, "0.5") {
170			t.Fatalf("拒绝原因应仍按正式限值说明，得到 %v", d.Reasons)
171		}
172		d2, err := l.RequestUse("M-1")
173		if err != nil || d2.Allowed {
174			t.Fatalf("申请使用应被拒绝并留痕，err=%v allowed=%v", err, d2.Allowed)
175		}
176		if !containsReason(d2.Reasons, "超差") {
177			t.Fatalf("留痕的拒绝原因应按正式限值显示超差，得到 %v", d2.Reasons)
178		}
179	
180		// M-2：停用，但有合格且未到期的证书——正式数据为停用限制。
181		mustRegister(t, l, "M-2", "温度计", 0.5)
182		mustAddCert(t, l, CertificateInput{
183			InstrumentID: "M-2", Number: "C-2", CalDate: "2026-09-01",
184			Expiry: "2027-09-01", Method: "m", Error: 0.1, Summary: "合格",
185		})
186		if err := l.SetStatus("M-2", StatusRetired); err != nil {
187			t.Fatalf("retire M-2: %v", err)
188		}
189		retired, err := l.Instrument("M-2")
190		if err != nil {
191			t.Fatalf("instrument M-2: %v", err)
192		}
193		retired.Status = StatusInUse
194		rv2, _ := l.Review("M-2")
195		rv2.Instrument.Status = StatusInUse
196		if rv2.CanUse || !containsReason(rv2.Reasons, "停用") {
197			t.Fatalf("把副本状态改成在用不应解除停用限制，得到 canUse=%v reasons=%v",
198				rv2.CanUse, rv2.Reasons)
199		}
200		d3, err := l.RequestUse("M-2")
201		if err != nil || d3.Allowed || !containsReason(d3.Reasons, "停用") {
202			t.Fatalf("停用器具申请使用仍应被拒绝且原因含停用，err=%v decision=%+v", err, d3)
203		}
204	
205		// M-3：在用、证书合格且未到期——正式数据允许使用；调低副本限值或改成
206		// 停用都不能让它失去资格。
207		mustRegister(t, l, "M-3", "压力表", 1.0)
208		_ = l.SetStatus("M-3", StatusInUse)
209		mustAddCert(t, l, CertificateInput{
210			InstrumentID: "M-3", Number: "C-3", CalDate: "2026-09-01",
211			Expiry: "2027-09-01", Method: "m", Error: 0.8, Summary: "合格",
212		})
213		ok, err := l.Instrument("M-3")
214		if err != nil {
215			t.Fatalf("instrument M-3: %v", err)
216		}
217		ok.AllowedError = 0 // 正式限值 1.0 下 0.8 合格，副本限值 0 下应为超差。
218		ok.Status = StatusRetired
219		rv3, _ := l.Review("M-3")
220		rv3.Instrument.AllowedError = 0
221		rv3.Instrument.Status = StatusRetired
222		if !rv3.CanUse || rv3.Latest == nil || !rv3.Latest.Pass {
223			t.Fatalf("原本允许使用的器具不应因副本整理失去资格：canUse=%v latest=%+v",
224				rv3.CanUse, rv3.Latest)
225		}
226		d4, err := l.RequestUse("M-3")
227		if err != nil || !d4.Allowed {
228			t.Fatalf("正式合格在用的器具申请应获准，err=%v decision=%+v", err, d4)
229		}
230	
231		// 证书内容与归属不因这些整理改变。
232		for _, want := range []struct {
233			id, number string
234			errV       float64
235		}{
236			{"M-1", "C-1", 0.8},
237			{"M-2", "C-2", 0.1},
238			{"M-3", "C-3", 0.8},
239		} {
240			c := l.LatestCertificate(want.id)
241			if c == nil || c.Number != want.number || c.Error != want.errV ||
242				c.InstrumentID != want.id {
243				t.Fatalf("证书内容或归属被器具副本整理改变：%+v", c)
244			}
245		}
246		// 正式登记的允许误差与状态保持原值。
247		assertOfficialInstrument(t, l, "M-1", "万用表", 0.5, StatusInUse, l.findInstrument("M-1").RegisteredAt)
248		assertOfficialInstrument(t, l, "M-2", "温度计", 0.5, StatusRetired, l.findInstrument("M-2").RegisteredAt)
249		assertOfficialInstrument(t, l, "M-3", "压力表", 1.0, StatusInUse, l.findInstrument("M-3").RegisteredAt)
250	}
251	
252	// TestReturnedInstrumentListCopyIsIndependent 验证列出器具返回的是独立副本：
253	// 改其中器具的字段、删去列表条目，只影响这一份列表；正式器具的数量和内容、
254	// 编号占用以及此后重新列出的结果都不变。
255	func TestReturnedInstrumentListCopyIsIndependent(t *testing.T) {
256		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
257		l := newTestLedger(t, clock)
258		mustRegister(t, l, "M-1", "万用表", 0.5)
259		mustRegister(t, l, "M-2", "温度计", 0.2)
260		savedAt1 := l.findInstrument("M-1").RegisteredAt
261	
262		list := l.Instruments()
263		if len(list) != 2 || list[0].ID != "M-1" || list[1].ID != "M-2" {
264			t.Fatalf("列表应按编号排序包含两件器具：%+v", list)
265		}
266		// 修改条目的全部展示字段并删去第二条。
267		list[0].ID = "M-FAKE"
268		list[0].Name = "列表里改的名"
269		list[0].AllowedError = 50
270		list[0].Status = StatusRetired
271		list[0].RegisteredAt = "2099-01-01T00:00:00Z"
272		list = append(list[:0], list[0]) // 只保留被篡改的那一条，相当于删去 M-2
273	
274		if len(l.Instruments()) != 2 {
275			t.Fatalf("删改返回列表不应改变正式器具数量，重新列出得到 %d 件", len(l.Instruments()))
276		}
277		assertOfficialInstrument(t, l, "M-1", "万用表", 0.5, StatusPending, savedAt1)
278		if _, err := l.Instrument("M-2"); err != nil {
279			t.Fatalf("从列表删去 M-2 不应删除正式器具：%v", err)
280		}
281		if _, err := l.Instrument("M-FAKE"); !errors.Is(err, ErrNotFound) {
282			t.Fatalf("列表中的伪造编号不应进入台账，得到 %v", err)
283		}
284		// 被“删除”的 M-2 编号仍占用，被“改名”的 M-1 编号也仍占用。
285		if _, err := l.Register(RegisterInput{ID: "M-2", Name: "重复", AllowedError: 1}); !IsValidation(err) {
286			t.Fatalf("M-2 编号仍应占用，得到 %v", err)
287		}
288		if _, err := l.Register(RegisterInput{ID: "M-1", Name: "重复", AllowedError: 1}); !IsValidation(err) {
289			t.Fatalf("M-1 编号仍应占用，得到 %v", err)
290		}
291	}
292	
293	// TestSeparatelyFetchedInstrumentResultsIndependent 验证分别取得的两份器具
294	// 结果互不影响：整理登记返回、两次按编号查询、两次列出与两次核对中的器具
295	// 信息，其他已取得的副本和台账正式记录都不变化。
296	func TestSeparatelyFetchedInstrumentResultsIndependent(t *testing.T) {
297		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
298		l := newTestLedger(t, clock)
299		registered, _ := l.Register(RegisterInput{ID: "M-1", Name: "万用表", AllowedError: 0.5})
300		savedAt := registered.RegisteredAt
301		if err := l.SetStatus("M-1", StatusInUse); err != nil {
302			t.Fatalf("set status: %v", err)
303		}
304	
305		q1, err := l.Instrument("M-1")
306		if err != nil {
307			t.Fatalf("instrument 1: %v", err)
308		}
309		q2, err := l.Instrument("M-1")
310		if err != nil {
311			t.Fatalf("instrument 2: %v", err)
312		}
313		list1 := l.Instruments()
314		list2 := l.Instruments()
315		r1, err := l.Review("M-1")
316		if err != nil {
317			t.Fatalf("review 1: %v", err)
318		}
319		r2, err := l.Review("M-1")
320		if err != nil {
321			t.Fatalf("review 2: %v", err)
322		}
323	
324		// 整理登记返回结果：其他全部副本与正式记录保持登记时的内容。
325		registered.ID = "M-FAKE"
326		registered.Name = "登记结果改名"
327		registered.AllowedError = 9
328		registered.Status = StatusRetired
329		registered.RegisteredAt = "2099-01-01T00:00:00Z"
330		for _, got := range []*Instrument{q1, q2, &list1[0], &list2[0], &r1.Instrument, &r2.Instrument} {
331			if got.ID != "M-1" || got.Name != "万用表" || got.AllowedError != 0.5 ||
332				got.Status != StatusInUse || got.RegisteredAt != savedAt {
333				t.Fatalf("整理登记返回结果影响了其他已取得副本：%+v", got)
334			}
335		}
336	
337		// 整理第一份按编号查询：第二份查询、两份列表、两份核对都不变。
338		q1.Name = "第一份查询改名"
339		q1.AllowedError = 8
340		q1.Status = StatusRetired
341		q1.ID = "M-Q1"
342		for _, got := range []*Instrument{q2, &list1[0], &list2[0], &r1.Instrument, &r2.Instrument} {
343			if got.Name != "万用表" || got.AllowedError != 0.5 ||
344				got.Status != StatusInUse || got.ID != "M-1" {
345				t.Fatalf("整理第一份查询影响了其他已取得副本：%+v", got)
346			}
347		}
348	
349		// 整理第一份列表与第一份核对：彼此独立，也不影响第二份与正式记录。
350		list1[0].Name = "第一份列表改名"
351		list1 = list1[:0]
352		r1.Instrument.Name = "第一份核对改名"
353		r1.Instrument.AllowedError = 7
354		if list2[0].Name != "万用表" || len(list2) != 1 {
355			t.Fatalf("整理第一份列表影响了第二份列表：%+v", list2)
356		}
357		if r2.Instrument.Name != "万用表" || r2.Instrument.AllowedError != 0.5 {
358			t.Fatalf("整理第一份核对影响了第二份核对：%+v", r2.Instrument)
359		}
360		if q2.Name != "万用表" || q2.Status != StatusInUse {
361			t.Fatal("整理列表或核对影响了此前取得的查询副本")
362		}
363		assertOfficialInstrument(t, l, "M-1", "万用表", 0.5, StatusInUse, savedAt)
364	}
365	
366	// TestRealStatusChangeUpdatesNewQueriesButFetchedCopiesStayFrozen 验证正式状态
367	// 切换成功后，新查询显示真实的新状态，而此前取得的器具副本仍保留获取时的
368	// 内容；展示数据的修改不随这次正常保存进入台账文件。
369	func TestRealStatusChangeUpdatesNewQueriesButFetchedCopiesStayFrozen(t *testing.T) {
370		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
371		path := filepath.Join(t.TempDir(), "ledger.json")
372		l, err := openAt(path, clock.now)
373		if err != nil {
374			t.Fatalf("open: %v", err)
375		}
376		mustRegister(t, l, "M-1", "万用表", 0.5)
377		mustRegister(t, l, "M-2", "温度计", 0.2)
378		if err := l.SetStatus("M-1", StatusInUse); err != nil {
379			t.Fatalf("set M-1 in-use: %v", err)
380		}
381		if err := l.SetStatus("M-2", StatusInUse); err != nil {
382			t.Fatalf("set M-2 in-use: %v", err)
383		}
384	
385		// 在正式切换为停用之前取得各入口的副本（此时两件器具都在用）。
386		beforeQ, _ := l.Instrument("M-1")
387		beforeList := l.Instruments()
388		beforeReview, _ := l.Review("M-1")
389		beforeRegistered, _ := l.Register(RegisterInput{ID: "M-3", Name: "压力表", AllowedError: 1.0})
390	
391		// 调用方先在副本上做展示整理，再执行正式状态切换。
392		beforeQ.AllowedError = 9
393		beforeList[0].Name = "列表展示名"
394		beforeReview.Instrument.AllowedError = 8
395		beforeRegistered.Status = StatusInUse // M-3 正式为待校准，副本伪造成在用
396	
397		// 通过正常状态切换功能把 M-1、M-2 正式改为停用（正常写盘）。
398		if err := l.SetStatus("M-1", StatusRetired); err != nil {
399			t.Fatalf("set M-1 retired: %v", err)
400		}
401		if err := l.SetStatus("M-2", StatusRetired); err != nil {
402			t.Fatalf("set M-2 retired: %v", err)
403		}
404	
405		// 新查询显示真实的新状态与正式限值/名称。
406		afterQ, err := l.Instrument("M-1")
407		if err != nil {
408			t.Fatalf("instrument after: %v", err)
409		}
410		if afterQ.Status != StatusRetired || afterQ.AllowedError != 0.5 || afterQ.Name != "万用表" {
411			t.Fatalf("正式切换后新查询应显示真实状态与登记信息：%+v", afterQ)
412		}
413		afterList := l.Instruments()
414		var afterListed *Instrument
415		for i := range afterList {
416			if afterList[i].ID == "M-1" {
417				afterListed = &afterList[i]
418			}
419		}
420		if afterListed == nil || afterListed.Status != StatusRetired || afterListed.Name != "万用表" {
421			t.Fatalf("正式切换后列出结果应显示新状态与正式名称：%+v", afterList)
422		}
423		afterReview, _ := l.Review("M-1")
424		if afterReview.Instrument.Status != StatusRetired ||
425			afterReview.CanUse || !containsReason(afterReview.Reasons, "停用") {
426			t.Fatalf("正式停用后核对应显示停用并拒绝使用：%+v", afterReview)
427		}
428		// M-3 未经正式切换仍为待校准，副本伪造成在用不影响它，也不影响 M-2。
429		if got, _ := l.Instrument("M-3"); got.Status != StatusPending {
430			t.Fatalf("M-3 应仍为待校准，得到 %+v", got)
431		}
432		if got, _ := l.Instrument("M-2"); got.Status != StatusRetired {
433			t.Fatalf("M-2 新查询应显示停用，得到 %+v", got)
434		}
435	
436		// 此前取得的副本保留获取时的内容与调用方自己的整理，不随正式变化更新。
437		if beforeQ.Status != StatusInUse || beforeQ.AllowedError != 9 || beforeQ.Name != "万用表" {
438			t.Fatalf("旧查询副本应保留获取时的在用状态与自身整理：%+v", beforeQ)
439		}
440		var oldListed *Instrument
441		for i := range beforeList {
442			if beforeList[i].ID == "M-1" {
443				oldListed = &beforeList[i]
444			}
445		}
446		if oldListed == nil || oldListed.Status != StatusInUse || oldListed.Name != "列表展示名" {
447			t.Fatalf("旧列表副本应保留获取时状态与自身整理：%+v", beforeList)
448		}
449		if beforeReview.Instrument.Status != StatusInUse || beforeReview.Instrument.AllowedError != 8 {
450			t.Fatalf("旧核对副本应保留获取时的在用状态与自身整理：%+v", beforeReview.Instrument)
451		}
452		if beforeRegistered.Status != StatusInUse {
453			t.Fatalf("登记返回副本被后续正式状态切换带动变化：%+v", beforeRegistered)
454		}
455	
456		// 重新打开同一台账：正式登记信息与真实状态保留，展示数据未进入文件。
457		reopened, err := openAt(path, clock.now)
458		if err != nil {
459			t.Fatalf("reopen: %v", err)
460		}
461		g1, _ := reopened.Instrument("M-1")
462		if g1.Name != "万用表" || g1.AllowedError != 0.5 || g1.Status != StatusRetired {
463			t.Fatalf("重开后 M-1 应为正式内容与停用状态：%+v", g1)
464		}
465		g2, _ := reopened.Instrument("M-2")
466		if g2.Name != "温度计" || g2.AllowedError != 0.2 || g2.Status != StatusRetired {
467			t.Fatalf("重开后 M-2 应为正式内容与真实状态：%+v", g2)
468		}
469		g3, _ := reopened.Instrument("M-3")
470		if g3.Name != "压力表" || g3.AllowedError != 1.0 || g3.Status != StatusPending {
471			t.Fatalf("重开后 M-3 应为正式内容与待校准状态：%+v", g3)
472		}
473		if len(reopened.Instruments()) != 3 {
474			t.Fatalf("重开后正式器具数量应为 3，得到 %d", len(reopened.Instruments()))
475		}
476	}
