475		mustRegister(t, la, "ONLY-A", "台账A器具", 0.1)
476		lb, err := openAt(pathB, clock)
477		if err != nil {
478			t.Fatalf("open B: %v", err)
479		}
480		mustRegister(t, lb, "ONLY-B", "台账B器具", 0.2)
481	
482		// 退出后再次打开同一台账仍能继续查询和操作。
483		reopenedA, err := openAt(pathA, clock)
484		if err != nil {
485			t.Fatalf("reopen A: %v", err)
486		}
487		if reopenedA.findInstrument("ONLY-A") == nil {
488			t.Fatal("台账A重开后丢失登记数据")
489		}
490		if reopenedA.findInstrument("ONLY-B") != nil {
491			t.Fatal("不同台账的数据混入了 A")
492		}
493		if _, err := reopenedA.Review("ONLY-B"); !errors.Is(err, ErrNotFound) {
494			t.Fatalf("台账 A 中不应能查到 B 的器具，得到 %v", err)
495		}
496		reopenedB, _ := openAt(pathB, clock)
497		if reopenedB.findInstrument("ONLY-A") != nil || reopenedB.findInstrument("ONLY-B") == nil {
498			t.Fatal("台账B数据被 A 污染")
499		}
500	
501		// 在重开的台账 A 上继续操作并再次持久化。
502		if err := reopenedA.SetStatus("ONLY-A", StatusRetired); err != nil {
503			t.Fatalf("在重开的台账上操作失败: %v", err)
504		}
505		again, _ := openAt(pathA, clock)
506		if again.findInstrument("ONLY-A").Status != StatusRetired {
507			t.Fatal("重开后所做的操作没有保存")
508		}
509	}
510	
511	func TestInvalidWritesLeaveNoHalfRecords(t *testing.T) {
512		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
513		path := filepath.Join(t.TempDir(), "ledger.json")
514		l, err := openAt(path, clock.now)
515		if err != nil {
516			t.Fatalf("open: %v", err)
517		}
518		mustRegister(t, l, "M-1", "万用表", 0.5)
519	
520		// 制造一连串失败操作，然后重开文件，确认没有半份记录。
521		_, _ = l.Register(RegisterInput{ID: " ", Name: "x", AllowedError: 1})
522		_, _ = l.Register(RegisterInput{ID: "M-1", Name: "x", AllowedError: 1})
523		_, _, _ = l.AddCertificate(CertificateInput{
