34	// setupTwoPassingCerts 构造本回归的标准场景：
35	//   - 器具 M-1 在用，允许误差 0.5；
36	//   - 较新证书 C-NEW：校准日期 2026-09-20，截止日 2026-10-20（先到期），
37	//     测得误差 -0.1，合格；
38	//   - 较早证书 C-OLD：校准日期 2026-09-10，截止日 2027-09-10（更长，
39	//     在整个场景覆盖的日期内始终未到期），测得误差 0.4，合格。
40	//
41	// backfill 为 true 时模拟“较早证书在较新证书之后补录”：先在 09-20 录入
42	// C-NEW，时钟拨到 09-25 再录入 C-OLD；为 false 时按校准日期先后录入。
43	// 两种录入顺序得到的最近证书、使用资格与历史顺序必须完全一致。
44	func setupTwoPassingCerts(t *testing.T, clock *fakeClock, backfill bool) *Ledger {
45		t.Helper()
46		l := newTestLedger(t, clock)
47		mustRegister(t, l, "M-1", "万用表", 0.5)
48		if err := l.SetStatus("M-1", StatusInUse); err != nil {
