92	// assertHistoryOnExpiryDay 核对截止日当天的历史证书视图：按校准日期由近到远
93	// 列出，且两张证书各自保留独立结论与截止日——较新证书已到期不把旧证书带成
94	// 到期，旧证书未到期也不把较新证书的到期误说成超差。
95	func assertHistoryOnExpiryDay(t *testing.T, r *InstrumentReview) {
96		t.Helper()
97		if len(r.History) != 2 {
98			t.Fatalf("历史应同时保留两张证书，得到 %d 张", len(r.History))
99		}
100		first := r.History[0]
101		second := r.History[1]
102		if first.Number != newerNumber || second.Number != olderNumber {
103			t.Fatalf("历史必须按校准日期由近到远为 %s、%s，得到 %s、%s",
104				newerNumber, olderNumber, first.Number, second.Number)
105		}
106		// 两张证书测得误差绝对值都不超过允许误差 0.5（0.4 同样在内）；
107		// 到期与否不改变合格结论：新证书到期不等于超差。
108		if !first.Pass {
109			t.Fatalf("较新证书 %s 应仍按允许误差判为合格，到期不应被说成超差：%+v",
110				newerNumber, first)
111		}
112		if !second.Pass {
