128	// 两张证书都合格，较新证书先到期。截止日前一天申请依据较新证书获准；
129	// 到截止日当天申请必须因较新（最近）证书到期而拒绝，即使较早证书合格且
130	// 有效期仍覆盖当天，也不能回退旧结论。
131	func TestNewerPassingCertExpiryDeniesWithoutFallingBackToOlder(t *testing.T) {
132		clock := &fakeClock{t: mustDate(t, "2026-09-20")}
