193		if err != nil {
194			t.Fatalf("can use after expiry: %v", err)
195		}
196		if after.Allowed || !containsReason(after.Reasons, newerNumber) {
197			t.Fatalf("截止日后仍应因最近证书 %s 到期而拒绝，得到 %v", newerNumber, after.Reasons)
198		}
199		assertLatestNewer(t, l)
200	}
