202	// TestReviewOnExpiryDayShowsNewerExpiredOlderStillValid 核对截止日当天的
203	// 按器具核对结果：最近证书是较新的 C-NEW 且已到期；历史按校准日期由近到远，
204	// 同时能看出新证书已到期、旧证书尚未到期；当前不可使用且原因只指向新证书。
205	// 两种录入顺序（先后录入 / 事后补录）结果一致。核对是只读操作：连续核对
206	// 不新增使用记录、不改动两张证书与器具状态。
207	func TestReviewOnExpiryDayShowsNewerExpiredOlderStillValid(t *testing.T) {
208		for _, backfill := range []bool{false, true} {
209			name := "按校准日期先后录入"
210			if backfill {
211				name = "较早证书事后补录"
212			}
213			t.Run(name, func(t *testing.T) {
214				clock := &fakeClock{t: mustDate(t, "2026-09-20")}
215				l := setupTwoPassingCerts(t, clock, backfill)
216				assertLatestNewer(t, l)
217	
218				clock.t = mustDate(t, "2026-10-19")
219				rBefore, err := l.Review("M-1")
220				if err != nil {
221					t.Fatalf("review before expiry: %v", err)
222				}
223				if !rBefore.CanUse || rBefore.Latest == nil || rBefore.Latest.Expired {
224					t.Fatalf("截止日前核对应可使用且最近证书未到期：canUse=%v latest=%+v",
225						rBefore.CanUse, rBefore.Latest)
226				}
227	
228				// 截止日当天核对：两次连续核对都必须得到同一结论，且不产生使用记录。
229				clock.t = mustDate(t, "2026-10-20")
230				usageBefore := len(l.UsageRecords())
231				r, err := l.Review("M-1")
232				if err != nil {
233					t.Fatalf("review on expiry day: %v", err)
234				}
235				r2, err := l.Review("M-1")
236				if err != nil {
237					t.Fatalf("second review: %v", err)
238				}
239				if got := len(l.UsageRecords()); got != usageBefore {
240					t.Fatalf("只读核对不应新增使用记录：%d -> %d", usageBefore, got)
241				}
242				for _, rv := range []*InstrumentReview{r, r2} {
243					if rv.CanUse {
244						t.Fatalf("截止日当天应不可使用，得到 %v", rv.Reasons)
245					}
246					if !containsReason(rv.Reasons, newerNumber) ||
247						!containsReason(rv.Reasons, newerExpiry) {
248						t.Fatalf("不可使用原因应指向 %s 及其截止日，得到 %v",
249							newerNumber, rv.Reasons)
250					}
251					if containsReason(rv.Reasons, olderNumber) ||
252						containsReason(rv.Reasons, "超差") {
253						t.Fatalf("原因不应涉及旧证书或超差：%v", rv.Reasons)
254					}
255					if rv.Latest == nil || rv.Latest.Number != newerNumber ||
256						!rv.Latest.Pass || !rv.Latest.Expired {
257						t.Fatalf("最近证书应为已到期但仍合格的 %s：%+v", newerNumber, rv.Latest)
258					}
259					assertHistoryOnExpiryDay(t, rv)
260					if rv.Instrument.Status != StatusInUse {
261						t.Fatalf("核对不应改动器具状态，得到 %s", rv.Instrument.Status)
262					}
263				}
264			})
265		}
266	}
267	
268	// TestBackfilledOlderLongerCertCannotReplaceExpiringNewer 明确保护补录场景：
269	// 较新证书先登记并先到期；较早证书在更晚日期补录、有效期更长。补录只增加
270	// 历史：最近证书仍是校准日期较新的一张；较新证书到期后申请仍被拒绝，
271	// 且这次拒绝在时钟继续前进后仍可查到、原因不被重写。
272	func TestBackfilledOlderLongerCertCannotReplaceExpiringNewer(t *testing.T) {
273		clock := &fakeClock{t: mustDate(t, "2026-09-20")}
274		l := setupTwoPassingCerts(t, clock, true)
275		assertLatestNewer(t, l)
276	
277		// 较新证书截止日当天产生一次因到期的拒绝（此时旧证书已补录在历史中）。
278		clock.t = mustDate(t, "2026-10-20")
279		d, err := l.RequestUse("M-1")
280		if err != nil {
281			t.Fatalf("request on expiry day: %v", err)
282		}
283		if d.Allowed || !containsReason(d.Reasons, newerNumber) ||
284			!containsReason(d.Reasons, newerExpiry) ||
285			containsReason(d.Reasons, olderNumber) {
286			t.Fatalf("补录旧证书后，截止日当天仍应仅因 %s 到期拒绝，得到 allowed=%v reasons=%v",
287				newerNumber, d.Allowed, d.Reasons)
288		}
289	
290		// 时钟继续前进后再次核对：拒绝记录仍在，原因保持申请当时冻结的内容；
291		// 旧证书仍未到期，新证书仍到期，最近证书不变。
292		clock.t = mustDate(t, "2026-11-01")
293		r, err := l.Review("M-1")
294		if err != nil {
295			t.Fatalf("review later: %v", err)
296		}
297		if r.Latest == nil || r.Latest.Number != newerNumber || !r.Latest.Expired {
298			t.Fatalf("最近证书仍应是已到期的 %s：%+v", newerNumber, r.Latest)
299		}
300		assertHistoryOnExpiryDay(t, r)
301		if len(r.Rejections) != 1 {
302			t.Fatalf("应能查到截止日当天那 1 次拒绝，得到 %d 条", len(r.Rejections))
303		}
304		rej := r.Rejections[0]
305		if rej.Allowed {
306			t.Fatal("留痕应保持拒绝结果")
307		}
308		if !strings.HasPrefix(rej.RequestedAt, "2026-10-20T") {
309			t.Fatalf("拒绝记录应保留申请时间 2026-10-20，得到 %s", rej.RequestedAt)
310		}
311		if !containsReason(rej.Reasons, newerNumber) ||
312			!containsReason(rej.Reasons, newerExpiry) ||
313			containsReason(rej.Reasons, olderNumber) {
314			t.Fatalf("拒绝原因应冻结为 %s 到期，补录旧证书不能重写：%v",
315				newerNumber, rej.Reasons)
316		}
317	}
318	
319	// TestAllowedRequestBeforeExpiryStaysAllowedAfterExpiry 保护历史冻结的另一面：
320	// 截止日前已经获准并保存的申请保留原结果，之后最近证书到期不会把它改成拒绝。
321	// 到期后的新申请另行拒绝，新旧记录各自保留申请当时的结论。
322	func TestAllowedRequestBeforeExpiryStaysAllowedAfterExpiry(t *testing.T) {
323		clock := &fakeClock{t: mustDate(t, "2026-09-20")}
324		l := setupTwoPassingCerts(t, clock, true)
325	
326		// 截止日前一天获准并保存。
327		clock.t = mustDate(t, "2026-10-19")
328		ok, err := l.RequestUse("M-1")
329		if err != nil || !ok.Allowed {
330			t.Fatalf("截止日前应获准，err=%v reasons=%v", err, ok.Reasons)
331		}
332	
333		// 截止日当天再次申请被拒绝。
334		clock.t = mustDate(t, "2026-10-20")
335		bad, err := l.RequestUse("M-1")
336		if err != nil || bad == nil || bad.Allowed {
337			t.Fatalf("截止日当天应拒绝，err=%v decision=%+v", err, bad)
338		}
339	
340		recs := l.UsageRecords()
341		if len(recs) != 2 {
342			t.Fatalf("应保留两次申请，得到 %d 条", len(recs))
343		}
344		// 按实际时刻排序：获准在前、拒绝在后；两条记录的结论各自冻结。
345		gotAllowed, gotRejected := recs[0], recs[1]
346		if !gotAllowed.Allowed || len(gotAllowed.Reasons) != 0 {
347			t.Fatalf("较早的获准记录不应被后来的到期改成拒绝：%+v", gotAllowed)
348		}
349		if !strings.HasPrefix(gotAllowed.RequestedAt, "2026-10-19T") {
350			t.Fatalf("获准记录时间应保留为 2026-10-19，得到 %s", gotAllowed.RequestedAt)
351		}
352		if gotRejected.Allowed ||
353			!containsReason(gotRejected.Reasons, newerNumber) ||
354			!containsReason(gotRejected.Reasons, newerExpiry) {
355			t.Fatalf("较晚的拒绝记录应保留 %s 到期原因：%+v", newerNumber, gotRejected)
356		}
357	
358		// Review 只汇总被拒绝记录；获准记录不出现在拒绝列表里，拒绝列表内容
359		// 不被后续操作改写。
360		r, err := l.Review("M-1")
361		if err != nil {
362			t.Fatalf("review: %v", err)
363		}
364		if len(r.Rejections) != 1 || r.Rejections[0].Allowed {
365			t.Fatalf("核对中只应有那 1 条拒绝，得到 %+v", r.Rejections)
366		}
367	}
368	
369	// TestExpiryBoundarySurvivesReopen 保护跨进程持久化：截止日前的获准与
370	// 截止日当天的拒绝都保存进台账文件后，用较晚日期重新打开同一文件，
371	// 最近证书仍是较新证书且已到期、旧证书未到期，历史记录原样可查；
372	// 结论不依赖内存中的假时钟状态。
373	func TestExpiryBoundarySurvivesReopen(t *testing.T) {
374		path := filepath.Join(t.TempDir(), "ledger.json")
375		clock := &fakeClock{t: mustDate(t, "2026-09-20")}
376		l, err := openAt(path, clock.now)
377		if err != nil {
378			t.Fatalf("open: %v", err)
379		}
380		mustRegister(t, l, "M-1", "万用表", 0.5)
381		if err := l.SetStatus("M-1", StatusInUse); err != nil {
382			t.Fatalf("set in-use: %v", err)
383		}
384		mustAddCert(t, l, CertificateInput{
385			InstrumentID: "M-1", Number: newerNumber, CalDate: newerCal,
386			Expiry: newerExpiry, Method: "规范A", Error: -0.1, Summary: "较新一次校准",
387		})
388		clock.t = mustDate(t, "2026-09-25")
389		mustAddCert(t, l, CertificateInput{
390			InstrumentID: "M-1", Number: olderNumber, CalDate: olderCal,
391			Expiry: olderExpiry, Method: "规范A", Error: 0.4, Summary: "补录的较早校准",
392		})
393	
394		clock.t = mustDate(t, "2026-10-19")
395		if ok, err := l.RequestUse("M-1"); err != nil || !ok.Allowed {
396			t.Fatalf("截止日前获准写入失败: %v", err)
397		}
398		clock.t = mustDate(t, "2026-10-20")
399		if bad, err := l.RequestUse("M-1"); err != nil || bad.Allowed {
400			t.Fatalf("截止日当天拒绝写入失败: %v", err)
401		}
402	
403		// 用晚得多的日期重新打开：较新证书到期、旧证书仍未到期，结论不变。
404		reopened, err := openAt(path, func() time.Time { return mustDate(t, "2027-01-05") })
405		if err != nil {
406			t.Fatalf("reopen: %v", err)
407		}
408		r, err := reopened.Review("M-1")
409		if err != nil {
410			t.Fatalf("review after reopen: %v", err)
411		}
412		if r.CanUse {
413			t.Fatalf("重开后仍应因最近证书到期而不可使用：%v", r.Reasons)
414		}
415		if r.Latest == nil || r.Latest.Number != newerNumber || !r.Latest.Expired || !r.Latest.Pass {
416			t.Fatalf("重开后最近证书应是已到期仍合格的 %s：%+v", newerNumber, r.Latest)
417		}
418		if len(r.History) != 2 {
419			t.Fatalf("重开后历史应有两张证书，得到 %d", len(r.History))
420		}
421		old := r.History[1]
422		if old.Number != olderNumber || old.Expired || !old.Pass {
423			t.Fatalf("重开后旧证书应仍合格未到期：%+v", old)
424		}
425		recs := reopened.UsageRecords()
426		if len(recs) != 2 {
427			t.Fatalf("重开后两次申请记录应原样保留，得到 %+v", recs)
428		}
429		if !recs[0].Allowed {
430			t.Fatal("重开后截止日前的获准记录被改写")
431		}
432		if recs[1].Allowed ||
433			!containsReason(recs[1].Reasons, newerNumber) ||
434			!containsReason(recs[1].Reasons, newerExpiry) {
435			t.Fatalf("重开后拒绝记录应保留 %s 到期原因：%+v", newerNumber, recs[1])
436		}
437	}
438

